using System.ComponentModel.DataAnnotations;

namespace AcxiomCRM.Web.Models;
public record LoginVm([Required,EmailAddress]string Email,[Required]string Password,bool RememberMe=false);
public record RegisterVm([Required,MaxLength(100)]string FullName,[Required,EmailAddress]string Email,[Required,MinLength(8)]string Password,[Required,Compare("Password")]string ConfirmPassword);
public class DashboardVm { public int Customers{get;set;} public int Leads{get;set;} public int OpenLeads{get;set;} public int Opportunities{get;set;} public int Won{get;set;} public int Lost{get;set;} public decimal Pipeline{get;set;} public List<Opportunity> Risky{get;set;}=new(); public Dictionary<string,int> LeadStatus{get;set;}=new(); public Dictionary<string,decimal> PipelineByStage{get;set;}=new(); }
public class CustomerVm { public int Id{get;set;} [Required,MaxLength(120)] public string CustomerName{get;set;}=""; [Required,EmailAddress] public string Email{get;set;}=""; [Required,RegularExpression(@"^[6-9]\d{9}$",ErrorMessage="Enter a valid 10-digit Indian mobile number.")] public string Phone{get;set;}=""; public string CompanyName{get;set;}=""; public string Address{get;set;}=""; public string City{get;set;}=""; public string State{get;set;}=""; public CustomerStatus Status{get;set;}=CustomerStatus.Active; public string? OwnerId{get;set;} }
public class LeadVm { public int Id{get;set;} [Required] public string LeadName{get;set;}=""; [Required,EmailAddress] public string Email{get;set;}=""; [Required,RegularExpression(@"^[6-9]\d{9}$")] public string Phone{get;set;}=""; public string CompanyName{get;set;}=""; public string Source{get;set;}="Website"; public LeadStatus Status{get;set;}=LeadStatus.New; public LeadPriority Priority{get;set;}=LeadPriority.Medium; [Range(0,100000000)] public decimal ExpectedValue{get;set;} public string? AssignedToId{get;set;} }
public class OpportunityVm { public int Id{get;set;} [Required] public string OpportunityName{get;set;}=""; [Range(1,int.MaxValue)] public int CustomerId{get;set;} public int? LeadId{get;set;} [Range(0.01,double.MaxValue)] public decimal Amount{get;set;} [Range(0,100)] public int Probability{get;set;} public OpportunityStage Stage{get;set;} public OpportunityStatus Status{get;set;}=OpportunityStatus.Open; [DataType(DataType.Date)] public DateTime ExpectedCloseDate{get;set;}=DateTime.UtcNow.Date.AddDays(30); public string? OwnerId{get;set;} public string? Notes{get;set;} }
public class FollowUpVm { public int? CustomerId{get;set;} public int? LeadId{get;set;} public int? OpportunityId{get;set;} [DataType(DataType.DateTime),Required] public DateTime FollowUpDate{get;set;}=DateTime.Now.AddDays(1); public FollowUpType FollowUpType{get;set;}=FollowUpType.Call; [Required] public string Subject{get;set;}=""; public string? Remarks{get;set;} public string? AssignedToId{get;set;} }
public class ActivityVm { public ActivityType ActivityType{get;set;}=ActivityType.Call; [Required] public string Subject{get;set;}=""; public string? Description{get;set;} public DateTime ActivityDate{get;set;}=DateTime.Now; public int? CustomerId{get;set;} public int? LeadId{get;set;} public ActivityStatus Status{get;set;}=ActivityStatus.Completed; public string? AssignedToId{get;set;} }

public class AdminUserVm { public string FullName{get;set;}=""; [EmailAddress,Required] public string Email{get;set;}=""; [Required,MinLength(8)] public string Password{get;set;}=""; public string Role{get;set;}="SalesExecutive"; }
